def labels_for(points, centers):
    labels = []
    for point in points:
        best = 0
        best_distance = None
        for c, center in enumerate(centers):
            distance = 0
            for d in range(len(point)):
                distance += (point[d] - center[d]) ** 2
            if best_distance is None or distance < best_distance:
                best = c
                best_distance = distance
        labels.append(best)
    return labels

def solve(data):
    points = data.get('data', [])
    count = data.get('K', 0)
    if len(points) == 0 or count <= 0:
        return [[], []]
    count = min(count, len(points))
    centers = [list(points[c]) for c in range(count)]
    iteration = 0
    while iteration < 20:
        labels = labels_for(points, centers)
        totals = [[0 for d in range(len(points[0]))] for c in range(count)]
        sizes = [0 for c in range(count)]
        for i in range(len(points)):
            c = labels[i]
            sizes[c] += 1
            for d in range(len(points[i])):
                totals[c][d] += points[i][d]
        updated = [list(center) for center in centers]
        for c in range(count):
            if sizes[c] > 0:
                for d in range(len(points[0])):
                    updated[c][d] = totals[c][d] / sizes[c]
        stable = updated == centers
        centers = updated
        iteration += 1
        if stable:
            break
    return [centers, labels_for(points, centers)]
